with b as (select min(observation_date) lo,max(observation_date) hi from {{ ref('fact_daily_demand') }}),e as (select p.promotion_id,p.start_date,p.end_date,date_diff('day',p.start_date,p.end_date)+1 n,ps.store_id,pk.sku_id from {{ ref('dim_promotion') }} p join {{ source('raw','promotion_stores') }} ps using(promotion_id) join {{ source('raw','promotion_skus') }} pk using(promotion_id)),c as (select e.*,x.calendar_date::date calendar_date,case when x.calendar_date<start_date then 'PRE' when x.calendar_date<=end_date then 'DURING' else 'POST' end period from e,lateral generate_series(start_date-n::integer,end_date+n::integer,interval 1 day)x(calendar_date)),o as (select store_id,sku_id,calendar_date,count(*) k,string_agg(promotion_id::varchar,',' order by promotion_id) ids from c where period='DURING' group by 1,2,3)
select c.promotion_id,c.store_id,c.sku_id,c.calendar_date,c.period,c.start_date promotion_start_date,c.end_date promotion_end_date,c.n promotion_duration_days,c.calendar_date between b.lo and b.hi is_observable,case when c.calendar_date<b.lo and period='PRE' then 'PRE_OUTSIDE_DATASET_BOUNDARY' when c.calendar_date>b.hi and period='POST' then 'POST_OUTSIDE_DATASET_BOUNDARY' when c.calendar_date not between b.lo and b.hi then 'DURING_OUTSIDE_DATASET_BOUNDARY' else 'COMPLETE' end boundary_status,case when is_observable then coalesce(d.realized_sales_units,0) end realized_sales_units,case when is_observable then coalesce(d.requested_demand_units,0) end requested_demand_units,case when is_observable then coalesce(d.lost_sales_units,0) end lost_sales_units,case when is_observable then coalesce(d.demand_censored_by_inventory,false) end demand_censored_by_inventory,pr.selling_price valid_selling_price,'STORE_SKU_DATE_VALIDITY_INTERVAL' price_semantics,case when is_observable then coalesce(d.realized_sales_units,0)*pr.selling_price end realized_revenue,coalesce(o.k,0)>1 promotion_overlap,o.ids overlapping_promotion_ids,d.brand_name,d.category_name,d.region_id,d.store_type,d.channel,'SYNTHETIC_REQUESTED_DEMAND_CONTEXT' requested_demand_semantics,'SYNTHETIC_LOST_SALES_CONTEXT' lost_sales_semantics from c cross join b left join {{ ref('fact_daily_demand') }} d on d.observation_date=c.calendar_date and d.store_id=c.store_id and d.sku_id=c.sku_id left join {{ source('raw','product_prices') }} pr on pr.store_id=c.store_id and pr.sku_id=c.sku_id and c.calendar_date between pr.valid_from and pr.valid_to left join o on o.store_id=c.store_id and o.sku_id=c.sku_id and o.calendar_date=c.calendar_date
